/**
 * NSE Comm Feed — activity.js
 *
 * Renders the activity feed from static JSON data and optionally
 * connects to the WebSocket emission layer for live updates.
 *
 * Two-layer architecture:
 *   1. Static: loads activity-feed.json (generated by deploy.py)
 *   2. Live:   connects to ws_emission.py WebSocket for real-time events
 *
 * Graceful degradation: if WebSocket is unavailable, static feed remains.
 */

(function () {
  'use strict';

  // --- Configuration ---

  const STATIC_FEED_URL = 'data/activity-feed.json';
  const WS_URL = 'ws://localhost:8765';   // Override via data-ws-url on body
  const MAX_EVENTS = 200;

  // Event type metadata
  const EVENT_TYPES = {
    analysis:   { label: 'Analysis',  icon: '\u{1F52C}', color: 'var(--accent)' },
    finding:    { label: 'Finding',   icon: '\u{2B50}', color: 'var(--preliminary)' },
    dm:         { label: 'Message',   icon: '\u{1F4AC}', color: 'var(--text-secondary)' },
    council:    { label: 'Council',   icon: '\u{1F3DB}', color: 'var(--accent)' },
    'tool-run': { label: 'Tool Run',  icon: '\u{2699}',  color: 'var(--text-dim)' },
    system:     { label: 'System',    icon: '\u{2699}',  color: 'var(--text-dim)' },
  };

  // Agent role → initials
  const AGENT_INITIALS = {
    'cartographer': 'CA', 'chief-geologist': 'CG', 'data-analyst': 'DA',
    'field-surveyor': 'FS', 'validation-officer': 'VO', 'research-librarian': 'RL',
    'pipeline-engineer': 'PE', 'pandoras-actor': 'PA', 'neuronist': 'NE',
    'aura': 'AU', 'mare': 'MA', 'victim': 'VI', 'orchestrator': 'SY',
  };

  // --- State ---

  let events = [];
  let activeFilter = 'all';
  let ws = null;
  let wsRetryCount = 0;
  const MAX_WS_RETRIES = 5;

  // --- DOM References ---

  const container = document.getElementById('feed-container');
  const emptyMsg = document.getElementById('feed-empty');
  const statusDot = document.getElementById('feed-status-dot');
  const statusText = document.getElementById('feed-status-text');
  const filterBtns = document.querySelectorAll('.feed-filter');

  // --- Rendering ---

  function renderFeed() {
    const filtered = activeFilter === 'all'
      ? events
      : events.filter(e => e.type === activeFilter);

    if (filtered.length === 0) {
      if (emptyMsg) emptyMsg.style.display = '';
      // Clear any existing event elements
      container.querySelectorAll('.feed-event').forEach(el => el.remove());
      return;
    }

    if (emptyMsg) emptyMsg.style.display = 'none';

    // Build HTML
    const html = filtered.map(renderEvent).join('');

    // Replace content (preserve empty msg element)
    container.querySelectorAll('.feed-event').forEach(el => el.remove());
    container.insertAdjacentHTML('beforeend', html);
  }

  function renderEvent(evt) {
    const meta = EVENT_TYPES[evt.type] || EVENT_TYPES.system;
    const agent = evt.agent || evt.from || 'unknown';
    const initials = AGENT_INITIALS[agent] || agent.substring(0, 2).toUpperCase();
    const ts = formatTimestamp(evt.timestamp);
    const tierBadge = evt.tier
      ? `<span class="tier tier-${evt.tier.toLowerCase()}">${evt.tier}</span>`
      : '';

    // DM events have from/to
    if (evt.type === 'dm') {
      const fromInit = AGENT_INITIALS[evt.from] || (evt.from || '??').substring(0, 2).toUpperCase();
      const toInit = AGENT_INITIALS[evt.to] || (evt.to || '??').substring(0, 2).toUpperCase();
      const fromName = agentDisplayName(evt.from);
      const toName = agentDisplayName(evt.to);

      return `
        <div class="feed-event feed-event-dm" data-type="${escAttr(evt.type)}">
          <div class="feed-event-avatar" style="border-color: ${meta.color}">
            <span>${escHtml(fromInit)}</span>
          </div>
          <div class="feed-event-content">
            <div class="feed-event-header">
              <span class="feed-event-agent">${escHtml(fromName)}</span>
              <span class="feed-event-arrow">&rarr;</span>
              <span class="feed-event-agent">${escHtml(toName)}</span>
              <span class="feed-event-type">${meta.label}</span>
              <span class="feed-event-time">${ts}</span>
            </div>
            <div class="feed-event-body">${escHtml(evt.body || '')}</div>
          </div>
        </div>`;
    }

    return `
      <div class="feed-event" data-type="${escAttr(evt.type)}">
        <div class="feed-event-avatar" style="border-color: ${meta.color}">
          <span>${escHtml(initials)}</span>
        </div>
        <div class="feed-event-content">
          <div class="feed-event-header">
            <span class="feed-event-agent">${escHtml(agentDisplayName(agent))}</span>
            <span class="feed-event-type">${meta.label}</span>
            ${tierBadge}
            <span class="feed-event-time">${ts}</span>
          </div>
          <div class="feed-event-title">${escHtml(evt.title || '')}</div>
          <div class="feed-event-body">${escHtml(evt.body || '')}</div>
          ${renderMetadata(evt.metadata)}
        </div>
      </div>`;
  }

  function renderMetadata(meta) {
    if (!meta) return '';
    const parts = [];
    if (meta.tile_id) parts.push(`Tile: ${meta.tile_id}`);
    if (meta.findings_count > 0) parts.push(`${meta.findings_count} finding(s)`);
    if (meta.stage) parts.push(`Stage: ${meta.stage}`);
    if (meta.confidence) parts.push(`Confidence: ${(meta.confidence * 100).toFixed(0)}%`);
    if (meta.duration_seconds) parts.push(`Duration: ${(meta.duration_seconds / 60).toFixed(1)}m`);
    if (parts.length === 0) return '';
    return `<div class="feed-event-meta">${parts.map(p => `<span>${escHtml(p)}</span>`).join('')}</div>`;
  }

  // --- Time Formatting ---

  function formatTimestamp(iso) {
    if (!iso) return '';
    try {
      const d = new Date(iso);
      const now = new Date();
      const diffMs = now - d;
      const diffMin = Math.floor(diffMs / 60000);

      if (diffMin < 1) return 'just now';
      if (diffMin < 60) return `${diffMin}m ago`;
      if (diffMin < 1440) return `${Math.floor(diffMin / 60)}h ago`;

      // Older than 24h — show date
      return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
        + ' ' + d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
    } catch (e) {
      return iso.substring(0, 16).replace('T', ' ');
    }
  }

  // --- Agent Display ---

  function agentDisplayName(role) {
    if (!role) return 'Unknown';
    return role.replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  }

  // --- Filters ---

  function setupFilters() {
    filterBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        filterBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        activeFilter = btn.dataset.filter;
        renderFeed();
      });
    });
  }

  // --- Static Data Loading ---

  async function loadStaticFeed() {
    try {
      const resp = await fetch(STATIC_FEED_URL);
      if (!resp.ok) return;
      const data = await resp.json();
      if (Array.isArray(data)) {
        events = data;
      } else if (data.events) {
        events = data.events;
      }
      renderFeed();
    } catch (e) {
      // No static feed yet — that's fine
    }
  }

  // --- WebSocket Live Layer ---

  function connectWebSocket() {
    const wsUrl = document.body.dataset.wsUrl || WS_URL;

    try {
      ws = new WebSocket(wsUrl);
    } catch (e) {
      setStatus('offline', 'Static feed only');
      return;
    }

    ws.onopen = () => {
      wsRetryCount = 0;
      setStatus('live', 'Live');
    };

    ws.onmessage = (msg) => {
      try {
        const data = JSON.parse(msg.data);
        handleWSMessage(data);
      } catch (e) {
        // Malformed message — ignore
      }
    };

    ws.onclose = () => {
      setStatus('offline', 'Disconnected');
      // Retry with exponential backoff
      if (wsRetryCount < MAX_WS_RETRIES) {
        wsRetryCount++;
        const delay = Math.min(1000 * Math.pow(2, wsRetryCount), 30000);
        setTimeout(connectWebSocket, delay);
      } else {
        setStatus('offline', 'Static feed only');
      }
    };

    ws.onerror = () => {
      setStatus('offline', 'Connection error');
    };
  }

  function handleWSMessage(data) {
    if (data.type === 'state_snapshot' && data.activity_feed) {
      // Full snapshot — replace events with feed data
      events = data.activity_feed;
      renderFeed();
    } else if (data.type === 'activity_event' && data.event) {
      // Incremental event — prepend
      prependEvent(data.event);
    }
  }

  function prependEvent(evt) {
    // Deduplicate by ID
    if (evt.id && events.some(e => e.id === evt.id)) return;

    events.unshift(evt);
    if (events.length > MAX_EVENTS) {
      events = events.slice(0, MAX_EVENTS);
    }

    // If filter matches, render the new event with animation
    if (activeFilter === 'all' || evt.type === activeFilter) {
      if (emptyMsg) emptyMsg.style.display = 'none';
      const html = renderEvent(evt);
      const temp = document.createElement('div');
      temp.innerHTML = html;
      const el = temp.firstElementChild;
      if (el) {
        el.classList.add('feed-event-new');
        const firstEvent = container.querySelector('.feed-event');
        if (firstEvent) {
          container.insertBefore(el, firstEvent);
        } else {
          container.appendChild(el);
        }
        // Remove animation class after transition
        setTimeout(() => el.classList.remove('feed-event-new'), 600);
      }
    }
  }

  // --- Status Indicator ---

  function setStatus(state, text) {
    if (statusDot) {
      statusDot.className = 'feed-status-dot ' + state;
    }
    if (statusText) {
      statusText.textContent = text;
    }
  }

  // --- Utilities ---

  function escHtml(s) {
    if (!s) return '';
    const d = document.createElement('div');
    d.textContent = s;
    return d.innerHTML;
  }

  function escAttr(s) {
    return (s || '').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }

  // --- Init ---

  document.addEventListener('DOMContentLoaded', () => {
    setupFilters();
    loadStaticFeed();
    connectWebSocket();
  });

})();
